                post_hook={
                    "sql": "CREATE OR REPLACE TABLE saadaa-wh.maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED_INTERMEDIATE AS SELECT CAST(JSON_EXTRACT_SCALAR(r.`order`,\'$.name\') AS STRING) AS order_name, CAST(order_line_item_id AS STRING) AS order_item_id, CAST(JSON_EXTRACT_SCALAR(r.`order`,\'$.created_at\') AS TIMESTAMP) AS order_date, request_number as return_request_number, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN r.created_at else null end as return_requested_at, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN cast(CAST(JSON_EXTRACT_SCALAR(r.approved,\'$.created_at\') AS TIMESTAMP)as datetime) else null end as return_approved_at, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$. refund.refunded_at\') AS TIMESTAMP) else null end AS refunded_at, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) and not (lower(status) in (\'rejected\',\'requested\')) THEN 1 else 0 end as Return_Flag, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN status else null end AS return_approval_status, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN r.request_type else null end AS return_request_type, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN datetime(cast(JSON_EXTRACT_SCALAR(r.inspected,\'$.created_at\') AS TIMESTAMP)) else null end AS return_inspected_date, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN datetime(cast(JSON_EXTRACT_SCALAR(r.received,\'$.created_at\') AS TIMESTAMP)) else null end AS return_received_date, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN datetime(cast(JSON_EXTRACT_SCALAR(r.received,\'$.created_at\') AS TIMESTAMP)) else null end AS return_date, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.reason\') AS STRING) else null end AS return_reason, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.shop_price.return_quantity\') AS INT64) else null end AS returned_quantity, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.shop_price.total_discount\') AS FLOAT64) else null end AS total_discount, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.shop_price.actual_amount\') AS FLOAT64) else null end AS actual_amount, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.shop_price.total_tax\') AS FLOAT64) else null end AS total_tax, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.return_location.facility_code\') AS STRING) else null end AS return_facility_code, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.return_location.inStoreReturnExchange\') AS STRING) else null end AS in_store_return_exchange, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.return_location.updated_at\') AS TIMESTAMP) else null end AS return_updated_at, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN SAFE_CAST(JSON_EXTRACT_SCALAR(l,\'$.return_fee\') AS FLOAT64) else null end AS return_fee, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.original_product.title\') AS STRING) else null end AS returned_product_name, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.original_product.variant_title\') AS STRING) else null end AS returned_product_variant, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.original_product.sku\') AS STRING) else null end AS returned_sku, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.original_product.price\') AS STRING) else null end AS returned_product_price, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(shipping,\'$.shipping_company\') AS STRING) else null end AS shipping_courier, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(shipping,\'$.awb\') AS STRING) else null end AS awb, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(shipping,\'$.shipment_status\') AS STRING) else null end AS shipping_status, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.exchange_product.title\') AS STRING) else null end AS exchange_product_name, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.exchange_product.variant_title\') AS STRING) else null end AS exchange_product_variant, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.exchange_product.sku\') AS STRING) else null end AS exchange_sku, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.exchange.order.total_price\') AS FLOAT64) else null end AS exchange_product_total_price, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.exchange.order.name\') AS STRING) else null end AS exchange_product_order_name, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) else null end AS return_line_item_id, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.exchange.order.exchange_status\') AS STRING) else null end AS exchange_status, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.refund.requested_mode\') AS STRING) else null end AS refund_request_mode, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.refund.status\') AS STRING) else null end AS refund_status, CASE WHEN (CAST(order_line_item_id AS STRING)) = CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) THEN CAST(JSON_EXTRACT_SCALAR(l,\'$.refund.refunded_amount.shop_money.amount\') AS FLOAT64) else null end AS refunded_amount FROM `saadaa-wh.MAPLEMONK.returnsprime_returns_exchanges` AS r LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(r.`order`,\'$.fulfillments\')) AS fulfillment_json LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(fulfillment_json,\'$.line_items\')) AS order_line_item_id LEFT JOIN UNNEST(r.line_items) AS l LEFT JOIN UNNEST(JSON_EXTRACT_ARRAY(l,\'$.shipping\')) AS shipping ON CAST(JSON_EXTRACT_SCALAR(l,\'$.id\') AS STRING) = CAST(order_line_item_id AS STRING) ; create or replace table saadaa-wh.maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED as select r.*, m.original_return_request_date, m.no_of_return_requests_initiated, m.list_of_couriers_assigned, case when lower(a.shipment_status) like \'%picked up from customer%\' then a.shipment_updated_at end as estimated_pickup_date, coalesce(sr.refund_amount,cf.refund_amount) as total_refund_amount, coalesce(sr.processed_at,cf.Last_checked_at) as refund_processed_at, coalesce(sr.created_at,cf.Added_On) as refund_created_at from ( select *, row_number() over (partition by order_name,order_item_id order by return_flag desc,return_requested_at desc) as rw from saadaa-wh.maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED_INTERMEDIATE where return_requested_at is not null ) r left join (select order_name,order_item_id, min(return_requested_at) as original_return_request_date, count(distinct return_requested_at) as no_of_return_requests_initiated, array_agg(upper(shipping_courier)) as list_of_couriers_assigned from (select * from saadaa-wh.maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED_INTERMEDIATE order by return_requested_at asc) where shipping_courier is not null group by 1,2) m on r.order_name = m.order_name and r.order_item_id = m.order_item_id left join (with refund as( select order_name, awb, count(*) as count from maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED_INTERMEDIATE WHERE AWB IS NOT NULL GROUP BY 1,2 ) select sr.contact_name as order_name, JSON_EXTRACT_SCALAR(notes,\'$.refund\') as Order_name_awb, r.count, max(cast(PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', created_at) as datetime)) AS Created_at, max(cast(PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', processed_at) as datetime)) AS Processed_at, safe_divide(sum(ifnull(cast(amount as float64),0)),r.count) as refund_amount from maplemonk.saadaa_shopify_razorpay_refunds sr left join refund r on sr.contact_name = replace(r.order_name,\'#\',\'\') and cast(JSON_EXTRACT_SCALAR(notes,\'$.refund\')as string) = concat(r.order_name,awb) where purpose = \'refund\' and status = \'processed\' and cast(PARSE_DATETIME(\'%d/%m/%Y %H:%M:%S\', created_at) as datetime) > \'2025-03-31\' and JSON_EXTRACT_SCALAR(notes,\'$.refund\') is not null group by 1,2,3) sr on sr.order_name = replace(r.order_name,\'#\',\'\') and sr.Order_name_awb = concat(r.order_name,awb) left join (with refund as( select order_name, awb, count(*) as count from maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED_INTERMEDIATE WHERE AWB IS NOT NULL GROUP BY 1,2 ) select cf.transfer_id as order_name, remarks as Order_name_awb, r.count, max(DATETIME(CASE WHEN LENGTH(Added_On) = 19 THEN PARSE_DATETIME(\'%Y-%m-%dT%H:%M:%S\', Added_On) WHEN LENGTH(Added_On) = 16 THEN PARSE_DATETIME(\'%Y-%m-%dT%H:%M\', Added_On) ELSE NULL END)) AS Added_On, max(DATETIME(CASE WHEN LENGTH(Last_checked_at) = 19 THEN PARSE_DATETIME(\'%Y-%m-%dT%H:%M:%S\', Last_checked_at) WHEN LENGTH(Last_checked_at) = 16 THEN PARSE_DATETIME(\'%Y-%m-%dT%H:%M\', Last_checked_at) ELSE NULL END)) AS Last_checked_at, safe_divide(sum(ifnull(cast(Amount as float64),0)),r.count) as refund_amount from maplemonk.saadaa_s3_saadaa_cashfree cf left join refund r on cf.transfer_id = replace(r.order_name,\'#\',\'\') and cast(remarks as string) = concat(r.order_name,awb) where lower(status) = \'success\' and remarks is not null group by 1,2,3) cf on cf.order_name = replace(r.order_name,\'#\',\'\') and cf.Order_name_awb = concat(r.order_name,awb) left join ( select * from (select *, row_number() over (partition by order_name,order_line_item_id,shipment_status order by return_flag desc,created_at desc,shipment_updated_at asc) as rw1 from ( SELECT _airbyte_data, JSON_VALUE( (SELECT shipping_obj FROM UNNEST(JSON_QUERY_ARRAY(line_item, \'$.shipping\')) AS shipping_obj LIMIT 1), \'$.tracking_updated_at\' ) AS shipment_updated_at, JSON_VALUE(_airbyte_data, \'$.created_at\') AS created_at, JSON_VALUE(_airbyte_data, \'$.order.name\') AS order_name, JSON_VALUE(line_item, \'$.id\') AS order_line_item_id, JSON_VALUE( (SELECT shipping_obj FROM UNNEST(JSON_QUERY_ARRAY(line_item, \'$.shipping\')) AS shipping_obj LIMIT 1), \'$.shipment_status\' ) AS shipment_status, CASE WHEN CAST(JSON_VALUE(line_item, \'$.id\') AS STRING) = CAST(JSON_EXTRACT_SCALAR(l, \'$.id\') AS STRING) AND not(LOWER(JSON_VALUE(_airbyte_data, \'$.status\')) IN (\'rejected\',\'requested\')) THEN 1 ELSE 0 END AS Return_Flag FROM `saadaa-wh.MAPLEMONK._airbyte_raw_returnsprime_returns_exchanges`, UNNEST(JSON_QUERY_ARRAY(_airbyte_data, \'$.line_items\')) AS line_item LEFT JOIN UNNEST(JSON_QUERY_ARRAY(_airbyte_data, \'$.line_items\')) AS l ) where lower(shipment_status) like \'%picked up from customer%\' ) where rw1=1 ) a on a.order_name = r.order_name and a.order_line_item_id = r.order_item_id and a.created_at = r.return_requested_at where rw=1; create or replace table saadaa-wh.maplemonk.saadaa_return_failures as select date(i.order_date) as date, i.shipping_courier, count(*) as failure_returns from saadaa-wh.maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED_INTERMEDIATE i left join saadaa-wh.maplemonk.SAADAA_RETURNSPRIME_CONSOLIDATED r on i.order_name = r.order_name and i.order_item_id = r.order_item_id where i.shipping_courier is not null and not(i.return_requested_at = r.return_requested_at) group by 1,2;",
                    "transaction": true
                }
            ) }}
